/* ----- Summary cards ----- */
.summary-row {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));
  gap: 14px;
  margin: 16px 0 18px;
}

.summary-card {
  background: linear-gradient(180deg, #ffffff 0%, #f8fafc 100%);
  border-radius: 14px;
  padding: 16px 14px;
  text-align: center;
  box-shadow: 0 8px 18px rgba(15, 23, 42, 0.06);
  border: 1px solid rgba(148, 163, 184, 0.18);
  transition: var(--transition);
}

.summary-card:hover {
  box-shadow: var(--shadow-hover);
}

.summary-card.summary-total {
  border-color: rgba(99, 102, 241, 0.35);
  background: linear-gradient(135deg, #ffffff 0%, #eef2ff 100%);
}

.summary-label {
  display: block;
  font-size: 12px;
  color: var(--text-light);
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.04em;
}

.summary-value {
  display: block;
  font-size: 1.6rem;
  font-weight: 800;
  color: var(--text);
  margin-top: 6px;
}

.summary-total .summary-value {
  color: var(--primary);
}

/* ----- Subject stats ----- */
.subject-stats-card {
  margin-bottom: 16px;
  padding: 14px 16px;
  border-radius: 14px;
  border: 1px solid rgba(148, 163, 184, 0.18);
}

.subject-stats-header {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  margin-bottom: 8px;
}

.subject-stats-title {
  font-size: 13px;
  font-weight: 700;
  color: var(--text);
}

.subject-stats-total {
  font-size: 12px;
  color: var(--text-light);
}

.subject-stats-list {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}

.subject-stat-chip {
  font-size: 12px;
  padding: 4px 10px;
  border-radius: 999px;
  background: var(--primary-bg);
  color: var(--primary);
}

