/* ----- Compact stats strip ----- */
.stats-strip {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 6px;
  margin-top: 12px;
  padding: 8px 12px;
  border-radius: 10px;
  background: rgba(248, 250, 252, 0.85);
  border: 1px solid rgba(148, 163, 184, 0.18);
  font-size: 12.5px;
  color: var(--text-light);
}

.stats-strip-item {
  color: #475569;
}

.stats-strip-item strong {
  font-weight: 700;
  color: var(--text);
}

.stats-strip-total {
  font-weight: 600;
  color: var(--primary);
}

.stats-strip-total .stats-strip-num {
  font-size: 14px;
  font-weight: 800;
}

.stats-strip-sep {
  color: rgba(148, 163, 184, 0.6);
  font-size: 11px;
}

.stats-strip-pipe {
  margin: 0 2px;
  color: rgba(148, 163, 184, 0.5);
  font-size: 13px;
}

.stats-strip-subject {
  padding: 2px 8px;
  border-radius: 999px;
  background: var(--primary-bg);
  color: var(--primary);
  font-size: 11.5px;
  font-weight: 600;
}
